import { Component } from '@angular/core';
import { Router } from '@angular/router';

@Component({
  selector: 'app-header',
  templateUrl: './header.component.html',
  styleUrls: ['./header.component.scss']
})
export class HeaderComponent {
  constructor(private router: Router) { }

  goHome(): void {
    this.router.navigate(['/']);
  }
}
<header class="bg-cyan/90 backdrop-blur-sm shadow-lg border-b border-cyan/20 sticky top-0 z-50">
  <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-3">
    <div class="flex items-center justify-between">
      <div class="flex items-center space-x-2 sm:space-x-3">
        <div class="w-8 h-8 sm:w-10 sm:h-10 bg-gradient-to-r from-cyan to-dark-cyan rounded-xl flex items-center justify-center">
          <span class="text-white font-bold text-sm sm:text-lg">H</span>
        </div>
        <h1 class="text-lg sm:text-xl font-bold text-white">Control Union</h1>
      </div>

      <div class="flex items-center space-x-1 sm:space-x-2">
        <button 
          (click)="goHome()"
          class="p-1.5 sm:p-2 rounded-lg hover:bg-dark-cyan/20 transition-colors"
          title="Go to Home">
          <svg class="w-5 h-5 sm:w-6 sm:h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6"/>
          </svg>
        </button>
      </div>
    </div>
  </div>
</header>
